using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Musikbox {public static partial class AudioAdvanced {
 public static string ExtractOriginal(IList<Song> songs,string parent,string ffmpeg,Action check,Action<int,int,string> progress){string stage=BatchFiles.Stage(parent);try{for(int i=0;i<songs.Count;i++){check();var song=songs[i];progress(i,songs.Count,song.Title);string error;string probe=Path.Combine(Path.GetDirectoryName(ffmpeg),"ffprobe"+Path.GetExtension(ffmpeg));string codec=Ffmpeg.Run(probe,"-v error -select_streams a:0 -show_entries stream=codec_name -of default=noprint_wrappers=1:nokey=1 "+Ffmpeg.Quote(Path.GetFullPath(song.Source)),check,out error).Trim();string ext=codec=="aac"||codec=="alac"?"m4a":codec=="mp3"?"mp3":codec=="opus"?"opus":codec=="vorbis"?"ogg":codec=="flac"?"flac":codec.StartsWith("pcm_")?"wav":null;if(ext==null)throw new ArgumentException("Die Audiospur kann nicht verlustfrei in ein unterstütztes Format übernommen werden. Bitte ein Zielformat auswählen. Codec: "+codec);string target=Path.Combine(stage,(i+1).ToString("D4")+" - "+Rules.SafeName(song.Artist+" - "+song.Title)+"."+ext);Ffmpeg.Run(ffmpeg,"-hide_banner -nostdin -v error -n -i "+Ffmpeg.Quote(Path.GetFullPath(song.Source))+" -map 0:a:0 -vn -c:a copy "+Ffmpeg.Quote(target),check,out error);if(!File.Exists(target)||new FileInfo(target).Length==0)throw new IOException("Keine Audiodatei erstellt.");}progress(songs.Count,songs.Count,"Fertig");return BatchFiles.Commit(stage,"Audioextraktion");}catch{BatchFiles.Cleanup(stage);throw;}}
}}
